select to_regclass('public.gym_join_requests') as join_table, to_regproc('public.register_gym_owner') as reg_rpc, to_regproc('public.member_gym_overview') as overview_rpc, to_regproc('public.admin_member_status_counts') as counts_rpc, to_regproc('public.platform_me') as platform_rpc; select (select count(*) from public.gyms) as gyms, (select count(*) from public.profiles) as profiles, (select count(*) from public.gym_settings) as settings, (select count(*) from public.gym_payment_methods) as rails, (select count(*) from public.gym_subscriptions) as subs, (select count(*) from auth.users) as auth_users;